import re

# Keywords related to flight booking issues
booking_keywords = [
    'booking', 'book', 'booked', 'reservation', 'reserve', 'reserved',
    'booking number', 'booking reference', 'cannot book', 'booking issue',
    'booking problem', 'booking error', 'flight booking', 'book a flight',
    'booking confirmation', 'booking failed', 'double booking', 'rebooking',
    'rebook', 'booking cancelled', 'booking canceled', 'booking change',
    'modify booking', 'cancel booking', 'booking not found'
]

# Let's count dialogs containing booking-related keywords per company
def has_booking_keywords(dialog_text):
    dialog_lower = dialog_text.lower()
    for kw in booking_keywords:
        if kw in dialog_lower:
            return True
    return False

booking_dialogs_by_company = Counter()
booking_dialog_ids_by_company = {}

for d in dataset:
    if has_booking_keywords(d['dialog']):
        booking_dialogs_by_company[d['company_id']] += 1
        if d['company_id'] not in booking_dialog_ids_by_company:
            booking_dialog_ids_by_company[d['company_id']] = []
        booking_dialog_ids_by_company[d['company_id']].append(d['dialog_id'])

print("Dialogs with booking-related keywords per company:")
for company, count in booking_dialogs_by_company.most_common():
    print(f"  {company}: {count}")
